    assertTrue(monitor.getException() instanceof InvalidConnectionException);
    assertNotNull(monitor.getException().getCause());
    assertTrue(monitor.getException().getCause() instanceof UnresolvedAddressException);
    // TODO: SSL, StartTLS
}

