public void testBind() {
    StudioProgressMonitor monitor = getProgressMonitor();
    ConnectionParameter connectionParameter = new ConnectionParameter(null, "localhost", ldapServer.getPort(), EncryptionMethod.NONE, NetworkProvider.APACHE_DIRECTORY_LDAP_API, AuthenticationMethod.SIMPLE, "uid=admin,ou=system", "secret", null, true, null);
